```js
let lastComputedAt = null;
async function load() {
  try {
    const res = await fetch('/api/metrics');
    const { rows, computed_at } = await res.json();
    if (computed_at !== lastComputedAt) {
      render(rows);
      lastComputedAt = computed_at;
