    document.getElementById('stamp').textContent = new Date(computed_at).toLocaleTimeString();
  } catch (e) { /* keep old data on screen, let the next tick retry */ }
}

let timer = setInterval(load, 15000);
document.addEventListener('visibilitychange', () => {
  if (document.hidden) clearInterval(timer);
  else { load(); timer = setInterval(load, 15000); }
});
```

